import { useState } from "react";
import Header from "./template/Header";
import ProductList from "./ProductList"; // hoặc đường dẫn tới ProductList của bạn
import { HashRouter, Routes, Route } from "react-router-dom";

function App() {
  // Đưa 2 state này lên App.js để dùng chung cho cả Header và ProductList
  const [currentCategory, setCurrentCategory] = useState("");
  const [currentBrand, setCurrentBrand] = useState("");

  return (
    <HashRouter>
      {/* Truyền hàm đổi danh mục vào Header */}
      <Header setCategory={setCurrentCategory} setBrand={setCurrentBrand} />
      
      <main style={{ marginTop: "80px" }}>
        <Routes>
          {/* Truyền các giá trị state vào ProductList */}
          <Route 
            path="/" 
            element={
              <ProductList 
                category={currentCategory} 
                setCategory={setCurrentCategory}
                brand={currentBrand}
                setBrand={setCurrentBrand}
              />
            } 
          />
          {/* Các route khác giữ nguyên */}
        </Routes>
      </main>
    </HashRouter>
  );
}

export default App;
